import React, { useState, useRef, DragEvent } from 'react';
import ColorThief from 'color-thief-browser';

interface ColorGuideProps {
  onBack: () => void;
  onHome: () => void;
  onNextStep: (color: string) => void;
}

const ColorGuide: React.FC<ColorGuideProps> = ({ onBack, onHome, onNextStep }) => {
  const [selectedColor, setSelectedColor] = useState('#f9f6f1');
  const [uploadedImage, setUploadedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  // 이미지 업로드 처리 (input)
  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        setUploadedImage(imageUrl);
      };
      reader.readAsDataURL(file);
    }
  };

  // 드래그 앤 드롭 업로드
  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(false);
    if (event.dataTransfer.files && event.dataTransfer.files[0]) {
      const file = event.dataTransfer.files[0];
      const reader = new FileReader();
      reader.onload = (e) => {
        const imageUrl = e.target?.result as string;
        setUploadedImage(imageUrl);
      };
      reader.readAsDataURL(file);
    }
  };
  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(true);
  };
  const handleDragLeave = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragActive(false);
  };

  // 이미지 onLoad에서 대표 컬러 추출
  const handleImageLoaded = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    const img = e.currentTarget;
    try {
      const colorThief = new ColorThief();
      const color: [number, number, number] = colorThief.getColor(img);
      const hexColor = '#' + color.map(x => x.toString(16).padStart(2, '0')).join('');
      setSelectedColor(hexColor);
    } catch (e) {
      // 실패 시 기본값 유지
    }
  };

  return (
    <div>
      <div className="card">
        <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
          <button className="btn btn-secondary" onClick={onBack}>
            ← 뒤로가기
          </button>
          <button className="btn-home" onClick={onHome}>
            🏠 홈
          </button>
          <h2 style={{ marginLeft: '20px', fontSize: '1.6rem', color: '#1e293b' }}>
            🎨 배경 컬러 추천받기
          </h2>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            📸 이미지에서 대표 컬러 추출하기
          </h3>
          <div
            className="card"
            style={{ textAlign: 'center', padding: '30px', border: dragActive ? '2px dashed #3b82f6' : undefined, background: dragActive ? '#f0f6ff' : undefined }}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
          >
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              onChange={handleImageUpload}
              style={{ display: 'none' }}
            />
            {!uploadedImage ? (
              <div>
                <div style={{ fontSize: '3rem', marginBottom: '20px' }}>📁</div>
                <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>이미지 업로드</h4>
                <p style={{ color: '#64748b', marginBottom: '20px' }}>
                  이미지를 클릭하거나, 이 영역에 드래그해서 업로드할 수 있어요
                </p>
                <button 
                  className="btn" 
                  onClick={() => fileInputRef.current?.click()}
                  style={{ 
                    fontSize: '1.1rem', 
                    padding: '12px 24px',
                    background: '#3b82f6',
                    color: 'white'
                  }}
                >
                  이미지 선택하기
                </button>
              </div>
            ) : (
              <div>
                <img
                  src={uploadedImage}
                  alt="업로드 이미지"
                  style={{
                    maxWidth: 220,
                    maxHeight: 220,
                    borderRadius: '16px',
                    marginBottom: '12px',
                    boxShadow: '0 2px 12px #e5e7eb',
                    objectFit: 'cover',
                    display: 'block',
                    marginLeft: 'auto',
                    marginRight: 'auto'
                  }}
                  crossOrigin="anonymous"
                  onLoad={handleImageLoaded}
                />
                <div style={{ margin: '18px 0 10px 0', textAlign: 'center' }}>
                  <span style={{ fontWeight: 700, color: '#334155', fontSize: '1rem' }}>추천 컬러</span><br/>
                  <span style={{
                    display: 'inline-block',
                    width: '40px',
                    height: '40px',
                    background: selectedColor,
                    borderRadius: '8px',
                    border: '2px solid #e5e7eb',
                    margin: '8px 0 4px 0',
                    verticalAlign: 'middle'
                  }} />
                  <div style={{ color: '#64748b', fontWeight: 'bold', fontSize: '1.05rem' }}>{selectedColor}</div>
                </div>
                <button 
                  className="btn" 
                  onClick={() => {
                    setUploadedImage(null);
                  }}
                  style={{ marginRight: '10px' }}
                >
                  다른 이미지 선택
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="mb-20">
          <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
            🎨 커스텀 컬러 선택
          </h3>
          <div className="card" style={{ textAlign: 'center', padding: '30px' }}>
            <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>직접 컬러 선택하기</h4>
            <input 
              type="color" 
              value={selectedColor}
              onChange={(e) => setSelectedColor(e.target.value)}
              style={{ 
                width: '100px', 
                height: '60px', 
                border: 'none', 
                borderRadius: '12px',
                cursor: 'pointer'
              }}
            />
            <div style={{ 
              marginTop: '15px', 
              padding: '10px', 
              background: selectedColor, 
              borderRadius: '8px',
              color: selectedColor === '#ffffff' ? '#000' : '#fff',
              fontWeight: 'bold'
            }}>
              선택된 컬러: {selectedColor}
            </div>
          </div>
        </div>

        <div className="mb-20" style={{ textAlign: 'center' }}>
          <button 
            className="btn" 
            style={{ 
              fontSize: '1.2rem', 
              padding: '15px 30px',
              background: '#3b82f6',
              color: 'white',
              border: 'none',
              borderRadius: '12px',
              cursor: 'pointer',
              fontWeight: 'bold'
            }}
            onClick={() => onNextStep(selectedColor)}
          >
            다음 단계: 텍스트 컬러 선택하기 →
          </button>
        </div>

        <div className="warning">
          <strong>💡 팁:</strong><br/>
          • 이미지를 업로드하면 대표 컬러 1개가 자동으로 추출됩니다<br/>
          • 필요하다면 아래에서 직접 컬러를 선택할 수 있습니다<br/>
